H = "stdlib.h"
F = [
("abort","void abort(void);","Ends the program abnormally.","Raises SIGABRT. If the signal is not caught or ignored, the program ends at once without calling the functions registered with atexit; buffered output is not flushed.","Does not return.","exit signal assert",None),
("abs","int abs(int j);","Returns the absolute value of an int.","The value of abs(INT_MIN) cannot be represented and is undefined.","The absolute value of j.","labs fabs",None),
("atexit","int atexit(void (*func)(void));","Registers a function to be called when the program ends normally.","At least 32 functions can be registered. They are called in the reverse order of registration by exit and when main returns.","0 on success, nonzero if the function could not be registered.","exit abort",None),
("atof","double atof(const char *nptr);","Converts a string to a double.","Equivalent to strtod(nptr, NULL) except that errors are not reported.","The converted value, or 0 if no conversion is possible.","strtod atoi",None),
("atoi","int atoi(const char *nptr);","Converts a string to an int.","Equivalent to (int)strtol(nptr, NULL, 10) except that errors are not reported. Leading white space is skipped.","The converted value, or 0 if no conversion is possible.","atol strtol sscanf",None),
("atol","long atol(const char *nptr);","Converts a string to a long.","Equivalent to strtol(nptr, NULL, 10) except that errors are not reported.","The converted value, or 0 if no conversion is possible.","atoi strtol",None),
("bsearch","void *bsearch(const void *key, const void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *));","Searches a sorted array with a binary search.","The array must be sorted in ascending order according to compar. compar(key, element) must return a negative value, zero or a positive value when key is less than, equal to or greater than the element.","A pointer to a matching element, or NULL if there is none.","qsort","#include <stdio.h>\n#include <stdlib.h>\n\nstatic int cmp(const void *a, const void *b)\n{\n    return *(const int *)a - *(const int *)b;\n}\n\nint main(void)\n{\n    int v[] = { 2, 4, 8, 16, 32 };\n    int key = 8;\n    int *p = bsearch(&key, v, 5, sizeof v[0], cmp);\n    if (p)\n        printf(\"found at index %d\\n\", (int)(p - v));\n    return 0;\n}"),
("calloc","void *calloc(size_t nmemb, size_t size);","Allocates zero-filled memory for an array.","The block is nmemb*size bytes long and every byte is 0. Free it with free.","A pointer to the block, or NULL if there is not enough memory.","malloc realloc free",None),
("div","div_t div(int numer, int denom);","Divides two ints and returns quotient and remainder.","The quotient is truncated toward zero. If the result cannot be represented the behavior is undefined.","A div_t with the members quot and rem.","ldiv",None),
("exit","void exit(int status);","Ends the program normally.","Functions registered with atexit are called in reverse order, open streams are flushed and closed, and the program ends with status. EXIT_SUCCESS and 0 mean success, EXIT_FAILURE means failure.","Does not return.","atexit abort _exit",None),
("free","void free(void *ptr);","Releases memory.","ptr must be NULL or a pointer returned by malloc, calloc or realloc that has not been freed. Freeing NULL does nothing.","Nothing.","malloc calloc realloc",None),
("getenv","char *getenv(const char *name);","Gets the value of an environment variable.","The returned string must not be modified and may be overwritten by later calls.","The value, or NULL if the variable is not set.","system",None),
("labs","long labs(long j);","Returns the absolute value of a long.","","The absolute value of j.","abs",None),
("ldiv","ldiv_t ldiv(long numer, long denom);","Divides two longs and returns quotient and remainder.","","An ldiv_t with the members quot and rem.","div",None),
("malloc","void *malloc(size_t size);","Allocates memory.","The block is not initialized. Free it with free. A request for size 0 may return NULL or a unique pointer.","A pointer to the block (suitably aligned for any type), or NULL if there is not enough memory.","calloc realloc free","#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main(void)\n{\n    char *s = malloc(32);\n    if (s == NULL)\n        return 1;\n    strcpy(s, \"dynamic\");\n    puts(s);\n    free(s);\n    return 0;\n}"),
("mblen","int mblen(const char *s, size_t n);","Returns the length of a multibyte character.","","The number of bytes, 0 for the null character, or -1 if the bytes are not a valid character. With s NULL: 0, because the encoding is not state-dependent.","mbtowc",None),
("mbstowcs","size_t mbstowcs(wchar_t *pwcs, const char *s, size_t n);","Converts a multibyte string to a wide-character string.","At most n wide characters are stored.","The number of wide characters stored (not counting the null), or (size_t)-1 on an invalid sequence.","wcstombs mbtowc",None),
("mbtowc","int mbtowc(wchar_t *pwc, const char *s, size_t n);","Converts a multibyte character to a wide character.","","The number of bytes used, 0 for the null character, or -1.","mblen wctomb",None),
("qsort","void qsort(void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *));","Sorts an array.","compar receives pointers to two elements and returns a negative value, zero or a positive value when the first is less than, equal to or greater than the second. Elements that compare equal may end up in any order.","Nothing.","bsearch","#include <stdio.h>\n#include <stdlib.h>\n\nstatic int cmp(const void *a, const void *b)\n{\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\n\nint main(void)\n{\n    int v[] = { 5, 1, 4, 2, 3 };\n    int i;\n    qsort(v, 5, sizeof v[0], cmp);\n    for (i = 0; i < 5; i++)\n        printf(\"%d \", v[i]);\n    putchar('\\n');\n    return 0;\n}"),
("rand","int rand(void);","Returns a pseudo-random number.","The sequence is determined by the seed set with srand; without a call to srand the seed is 1.","An integer from 0 to RAND_MAX.","srand",None),
("realloc","void *realloc(void *ptr, size_t size);","Changes the size of an allocated block.","The contents are kept up to the smaller of the old and new size. The block may move. With ptr NULL it works like malloc. If it fails, the old block is left alone.","A pointer to the new block, or NULL on failure.","malloc calloc free",None),
("srand","void srand(unsigned int seed);","Seeds the random number generator.","The same seed gives the same sequence from rand.","Nothing.","rand time",None),
("strtod","double strtod(const char *nptr, char **endptr);","Converts the start of a string to a double.","Skips leading white space, then reads an optional sign, digits with an optional decimal point and an optional exponent. If endptr is not NULL it receives a pointer to the first unconverted character.","The value. If the value is out of range, HUGE_VAL (with the sign) is returned or 0 for underflow and errno is set to ERANGE.","atof strtol",None),
("strtol","long strtol(const char *nptr, char **endptr, int base);","Converts the start of a string to a long.","base is 2 to 36, or 0 to accept a 0x prefix for hexadecimal and a leading 0 for octal. Leading white space and a sign are accepted. If endptr is not NULL it receives a pointer to the first unconverted character.","The value. On overflow LONG_MAX or LONG_MIN is returned and errno is set to ERANGE.","strtoul atol atoi",None),
("strtoul","unsigned long strtoul(const char *nptr, char **endptr, int base);","Converts the start of a string to an unsigned long.","Same as strtol except for the result type.","The value. On overflow ULONG_MAX is returned and errno is set to ERANGE.","strtol",None),
("system","int system(const char *command);","Runs a command through the shell.","With command NULL, system tells whether a command processor is available.","The exit status of the command; with a NULL argument nonzero if a shell is available.","getenv exit",None),
("wcstombs","size_t wcstombs(char *s, const wchar_t *pwcs, size_t n);","Converts a wide-character string to a multibyte string.","","The number of bytes stored (not counting the null), or (size_t)-1.","mbstowcs wctomb",None),
("wctomb","int wctomb(char *s, wchar_t wchar);","Converts a wide character to a multibyte character.","","The number of bytes stored, or -1.","mbtowc wcstombs",None),
]
